-- V26 complements the activity-board database foundations from docs/26.
-- Station rows and benefit package rows are generated from data/activity-board workbook.

alter table coupon_template
    add column if not exists coupon_kind varchar(64),
    add column if not exists source_activity varchar(128),
    add column if not exists applicable_station_types jsonb not null default '[]'::jsonb,
    add column if not exists applicable_fuel_types jsonb not null default '[]'::jsonb,
    add column if not exists applicable_member_levels jsonb not null default '[]'::jsonb;

alter table promotion_rule
    add column if not exists start_date date,
    add column if not exists end_date date,
    add column if not exists days_of_month jsonb not null default '[]'::jsonb,
    add column if not exists station_types jsonb not null default '[]'::jsonb,
    add column if not exists member_levels jsonb not null default '[]'::jsonb,
    add column if not exists points_multiplier numeric(8, 4) not null default 1.0000,
    add column if not exists settlement_mode varchar(64),
    add column if not exists source_sheet_name varchar(256),
    add column if not exists source_row_number integer;

alter table member
    add column if not exists e_enjoy_card_no varchar(64),
    add column if not exists usual_province varchar(64),
    add column if not exists member_tags jsonb not null default '[]'::jsonb,
    add column if not exists registered_at timestamptz,
    add column if not exists card_opened_at timestamptz;

create table if not exists station (
    station_code varchar(64) primary key,
    hos_code varchar(64),
    station_name varchar(256) not null,
    branch_company varchar(128),
    prefecture varchar(128),
    province varchar(64) not null default '新疆',
    city varchar(128),
    district varchar(128),
    address varchar(512),
    longitude numeric(12, 6),
    latitude numeric(12, 6),
    contact_name varchar(128),
    contact_phone varchar(64),
    station_type varchar(64) not null default 'gas_station',
    sales_scope jsonb not null default '[]'::jsonb,
    remark varchar(1024),
    source_sheet_name varchar(256),
    source_row_number integer,
    is_demo_data boolean not null default false,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now()
);
create index if not exists idx_station_city on station (city);
create index if not exists idx_station_hos_code on station (hos_code);

create table if not exists promotion_date_trigger (
    id bigserial primary key,
    activity_code varchar(128) not null,
    rule_id varchar(128),
    trigger_type varchar(64) not null,
    days_of_month jsonb not null default '[]'::jsonb,
    start_date date,
    end_date date,
    time_from time,
    time_to time,
    description varchar(512),
    source_sheet_name varchar(256),
    source_row_number integer,
    created_at timestamptz not null default now(),
    unique (activity_code, rule_id, trigger_type)
);

create table if not exists points_activity (
    activity_id varchar(128) primary key,
    rule_id varchar(128),
    activity_name varchar(256) not null,
    points_multiplier numeric(8, 4) not null default 1.0000,
    member_required boolean not null default true,
    start_date date,
    end_date date,
    days_of_month jsonb not null default '[]'::jsonb,
    station_types jsonb not null default '[]'::jsonb,
    station_provinces jsonb not null default '[]'::jsonb,
    fuel_types jsonb not null default '[]'::jsonb,
    included_categories jsonb not null default '[]'::jsonb,
    excluded_categories jsonb not null default '[]'::jsonb,
    status varchar(32) not null default 'ACTIVE',
    source_sheet_name varchar(256),
    source_row_number integer,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now()
);
create index if not exists idx_points_activity_status on points_activity (status);

create table if not exists member_points_change (
    change_id varchar(128) primary key,
    member_code varchar(64) not null,
    change_type varchar(64) not null,
    points_change bigint not null,
    total_points_after bigint not null,
    available_points_after bigint not null,
    source_type varchar(64) not null,
    source_id varchar(128),
    rule_id varchar(128),
    station_code varchar(64),
    operator_id varchar(128),
    operator_name varchar(128),
    reason varchar(1024),
    occurred_at timestamptz not null default now(),
    created_at timestamptz not null default now()
);
create index if not exists idx_member_points_change_member on member_points_change (member_code, occurred_at desc);
create index if not exists idx_member_points_change_source on member_points_change (source_type, source_id);

create table if not exists promotion_excluded_category (
    id bigserial primary key,
    rule_id varchar(128) not null,
    category_name varchar(128) not null,
    reason varchar(512),
    source_sheet_name varchar(256),
    created_at timestamptz not null default now(),
    unique (rule_id, category_name)
);

create table if not exists promotion_station_scope (
    id bigserial primary key,
    rule_id varchar(128) not null,
    scope_type varchar(32) not null default 'INCLUDE',
    station_code varchar(64),
    station_type varchar(64),
    province varchar(64),
    city varchar(128),
    source_sheet_name varchar(256),
    created_at timestamptz not null default now()
);
create unique index if not exists idx_promotion_station_scope_unique on promotion_station_scope (rule_id, scope_type, coalesce(station_code, ''), coalesce(station_type, ''), coalesce(province, ''), coalesce(city, ''));

create table if not exists benefit_package (
    package_code varchar(128) primary key,
    package_name varchar(256) not null,
    sales_channel varchar(128),
    sale_price numeric(18, 2) not null default 0,
    status varchar(32) not null default 'ACTIVE',
    source_sheet_name varchar(256),
    source_row_number integer,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now()
);

create table if not exists benefit_package_item (
    id bigserial primary key,
    package_code varchar(128) not null references benefit_package(package_code) on delete cascade,
    item_name varchar(512) not null,
    quantity numeric(18, 3) not null default 1,
    remark varchar(1024),
    source_row_number integer
);
create index if not exists idx_benefit_package_item_package on benefit_package_item (package_code);

create table if not exists benefit_package_purchase (
    purchase_id varchar(128) primary key,
    member_code varchar(64) not null,
    package_code varchar(128) not null,
    package_name varchar(256) not null,
    sale_price numeric(18, 2) not null default 0,
    payment_amount numeric(18, 2) not null default 0,
    station_code varchar(64),
    checkout_transaction_no varchar(128),
    status varchar(32) not null default 'PURCHASED',
    entitlement_snapshot jsonb not null default '[]'::jsonb,
    purchased_at timestamptz not null default now(),
    activated_at timestamptz,
    expired_at timestamptz,
    operator_id varchar(128),
    operator_name varchar(128),
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now()
);
create index if not exists idx_benefit_package_purchase_member on benefit_package_purchase (member_code, purchased_at desc);

on conflict (activity_code, rule_id, trigger_type) do update
set days_of_month = excluded.days_of_month,
    start_date = excluded.start_date,
    end_date = excluded.end_date,
    time_from = excluded.time_from,
    time_to = excluded.time_to,
    description = excluded.description;

on conflict (activity_id) do update
set points_multiplier = excluded.points_multiplier,
    days_of_month = excluded.days_of_month,
    station_types = excluded.station_types,
    station_provinces = excluded.station_provinces,
    fuel_types = excluded.fuel_types,
    included_categories = excluded.included_categories,
    excluded_categories = excluded.excluded_categories,
    status = excluded.status,
    updated_at = now();

on conflict (rule_id, category_name) do update set reason = excluded.reason;

on conflict do nothing;

on conflict (station_code) do update
set hos_code = excluded.hos_code,
    station_name = excluded.station_name,
    branch_company = excluded.branch_company,
    prefecture = excluded.prefecture,
    city = excluded.city,
    district = excluded.district,
    address = excluded.address,
    longitude = excluded.longitude,
    latitude = excluded.latitude,
    contact_name = excluded.contact_name,
    contact_phone = excluded.contact_phone,
    sales_scope = excluded.sales_scope,
    remark = excluded.remark,
    source_row_number = excluded.source_row_number,
    updated_at = now();

on conflict (package_code) do update
set package_name = excluded.package_name,
    sales_channel = excluded.sales_channel,
    sale_price = excluded.sale_price,
    status = excluded.status,
    updated_at = now();

delete from benefit_package_item where package_code like 'benefit-package-%';
;
